const fromWebhook = $input.first().json.body?.chatId;
const chatId = fromWebhook || '6537042237';
return [{ json: { chatId } }];

const rows = $input.all().map(i => i.json).filter(r => Object.keys(r).length > 0);
let chatId = "YOUR_CHAT_ID";
try { chatId = $("Get ChatId").first().json.chatId || "YOUR_CHAT_ID"; } catch(e) {}
const output = rows.length > 0 ? rows.map(r=>({...r,__chatId:chatId})) : [{__chatId:chatId}];
return output.map(r=>({json:r}));

const previousRows = $input.all().map(i => i.json);
const chatId = previousRows[0]?.__chatId || "YOUR_CHAT_ID";

const competitors = [
  { name: "Telmidtv",     urls: ["https://www.telmidtv.com/"] },
  { name: "Darsna",       urls: ["https://www.darsna.ma/"] },
  { name: "Sawbona",      urls: ["https://www.sawbona.ma/"] },
  { name: "Oustad",       urls: ["https://www.oustad.ma/"] },
  { name: "Moutamadris",  urls: ["https://www.moutamadris.ma/"] }
];

const items = [];
competitors.forEach(comp => {
  comp.urls.forEach(url => {
    items.push({ json: { competitor_name: comp.name, url, chatId, previousRows } });
  });
});

return items;

const item = $input.first().json;
const comp = $('Define Competitors').first().json;

// Detect DNS / network errors (onError:continueRegularOutput passes them through as JSON)
if (item.error || item.code === 'ENOTFOUND' || (typeof item === 'object' && JSON.stringify(item).includes('ENOTFOUND'))) {
  const previousRows = comp.previousRows || [];
  const key = `${comp.competitor_name}::${comp.url}`;
  const prev = previousRows.find(r => `${r.competitor_name}::${r.url}` === key);
  return [{ json: {
    competitor_name: comp.competitor_name,
    url: comp.url,
    chatId: comp.chatId,
    page_title: prev?.page_title || 'UNREACHABLE',
    meta_description: prev?.meta_description || '',
    headings: prev?.headings || '',
    text_preview: 'Site could not be reached (DNS/network error)',
    previous_title: prev?.page_title || 'First scan',
    title_changed: false,
    previous_headings: prev?.headings || '',
    is_first_scan: !prev,
    scraped_at: new Date().toISOString()
  }}];
}

// n8n HTTP text response can land in different fields depending on version
const html = (typeof item === 'string' ? item : item.data || item.body || item.html || item.text || JSON.stringify(item));


const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
const title = titleMatch ? titleMatch[1].trim() : 'N/A';

const metaMatch = html.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']+)["']/i);
const metaDesc = metaMatch ? metaMatch[1].trim() : '';

const headings = [];
for (const m of html.matchAll(/<h[1-3][^>]*>([^<]+)<\/h[1-3]>/gi)) {
  headings.push(m[1].trim());
  if (headings.length >= 8) break;
}

const textContent = html
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ').trim().substring(0, 2000);

const previousRows = comp.previousRows || [];
const key = `${comp.competitor_name}::${comp.url}`;
const prev = previousRows.find(r => `${r.competitor_name}::${r.url}` === key);

return [{
  json: {
    competitor_name: comp.competitor_name,
    url: comp.url,
    chatId: comp.chatId,
    page_title: title,
    meta_description: metaDesc,
    headings: headings.join(' | '),
    text_preview: textContent,
    previous_title: prev?.page_title || 'First scan',
    title_changed: prev ? title !== prev.page_title : false,
    previous_headings: prev?.headings || '',
    is_first_scan: !prev,
    scraped_at: new Date().toISOString()
  }
}];

const allResults = $input.all().map(i => i.json);
const chatId = allResults[0]?.chatId || 'YOUR_CHAT_ID';
return [{ json: { competitors: allResults, chatId } }];

const data = $input.first().json;
const today = new Date().toISOString().split('T')[0];

const prompt = `You are a competitive intelligence analyst for Darsy, a Moroccan educational platform targeting BAC and Brevet students in Morocco.

All competitors are Moroccan platforms. Analyze their pages with Moroccan context in mind (Moroccan curriculum, Arabic/French bilingual content, MAD pricing, Moroccan school calendar). Compare current vs previous data and identify changes:

${JSON.stringify(data.competitors, null, 2)}

Output ONLY valid JSON (no markdown, no code block, no explanation):
{"report_date":"${today}","executive_summary":"2-3 sentence overview in English","competitors":[{"name":"...","changes_detected":true,"changes":[{"type":"...","description":"...","significance":"high/medium/low","darsy_action":"..."}],"overall_assessment":"..."}],"strategic_recommendations":[{"priority":"high/medium/low","action":"...","reasoning":"..."}],"content_gaps":["Content competitors have that Darsy doesn't"]}`;

const body = {
  model: 'gpt-4o',
  max_tokens: 2000,
  messages: [
    { role: 'system', content: 'You are a competitive intelligence analyst. Always respond with valid JSON only — no markdown, no code blocks.' },
    { role: 'user', content: prompt }
  ]
};

return [{ json: { body, chatId: data.chatId } }];

const raw = $input.first().json;
const chatId = $('Build AI Prompt').first().json.chatId;

let report;
try {
  const text = raw.choices?.[0]?.message?.content || JSON.stringify(raw);
  const cleaned = text.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
  report = JSON.parse(cleaned);
} catch(e) {
  report = { executive_summary: 'Report parsing failed: ' + e.message, competitors: [] };
}

let msg = `🕵️ *Competitor Intelligence Report*\n📅 ${report.report_date || new Date().toISOString().split('T')[0]}\n\n`;
msg += `📋 *Summary:* ${report.executive_summary || 'N/A'}\n\n`;

(report.competitors || []).forEach(comp => {
  const icon = comp.changes_detected ? '🔴' : '🟢';
  msg += `${icon} *${comp.name}*\n`;
  (comp.changes || []).slice(0, 2).forEach(c => {
    msg += `   • [${c.significance}] ${c.description}\n`;
  });
  if (!comp.changes?.length) msg += `   No changes\n`;
  msg += '\n';
});

if (report.strategic_recommendations?.length) {
  msg += `🎯 *Actions for Darsy:*\n`;
  report.strategic_recommendations.slice(0, 3).forEach((r, i) => {
    msg += `  ${i+1}. [${r.priority}] ${r.action}\n`;
  });
}

const competitors = $('Aggregate Results').first().json.competitors;
return [{ json: { message: msg.substring(0, 4000), chatId, competitors } }];
